// Package npm checks package.json for dependencies pinned older than
// what's actually released, using git-pkgs/manifests to parse the manifest
// and an injected resolver.Resolver to look up latest releases.
package npm

import (
	"context"
	"fmt"
	"strings"

	"github.com/git-pkgs/manifests"

	"github.com/chains-project/yul/pkg/util/mismatch"
	"github.com/chains-project/yul/pkg/util/pins"
	"github.com/chains-project/yul/pkg/util/resolver"
)

const scheme = "npm"

// Checker implements manifestchecker.ManifestChecker for package.json.
type Checker struct {
	// Resolver resolves latest released versions. main.go wires up an
	// enrichment-backed resolver; tests inject a fake one.
	Resolver resolver.Resolver
}

func (Checker) Filename() string { return "package.json" }

func (c Checker) Check(before, after string) ([]mismatch.Mismatch, error) {
	return CheckPackageJSON(before, after, c.Resolver)
}

// parsePackageJSONPins parses package.json content and returns its
// exactly-pinned dependencies (no "^", "~", range, wildcard, tag, or
// protocol prefix) across dependencies, devDependencies,
// optionalDependencies, and peerDependencies.
func parsePackageJSONPins(content string) (map[string]pins.Pin, error) {
	result := make(map[string]pins.Pin)
	if strings.TrimSpace(content) == "" {
		return result, nil
	}

	parsed, err := manifests.Parse("package.json", []byte(content))
	if err != nil {
		return nil, fmt.Errorf("parsing package.json: %w", err)
	}

	for _, declaration := range parsed.Declarations {
		version, ok := pins.ExactVersion(declaration.Version, scheme, false)
		if !ok {
			continue
		}
		result[declaration.Location] = pins.Pin{
			Name:    declaration.Name,
			Version: version,
			PURL:    declaration.PURL,
		}
	}
	return result, nil
}

// CheckPackageJSON compares package.json content before and after a Write
// and reports any exactly-pinned package that is newly added or whose
// pinned version was just changed, and is older than the latest release res
// knows about. Packages the write didn't touch, or that aren't pinned
// exactly, are left alone.
func CheckPackageJSON(before, after string, res resolver.Resolver) ([]mismatch.Mismatch, error) {
	beforePins, err := parsePackageJSONPins(before)
	if err != nil {
		return nil, err
	}
	afterPins, err := parsePackageJSONPins(after)
	if err != nil {
		return nil, err
	}
	return pins.Diff(context.Background(), beforePins, afterPins, scheme, res)
}
package npm

import (
	"context"
	"testing"
)

// fakeResolver resolves latest versions from a fixed PURL->version map, so
// tests don't make real network requests.
type fakeResolver struct {
	latest  map[string]string
	lookups int
}

func (r *fakeResolver) LatestVersions(ctx context.Context, purls []string) (map[string]string, error) {
	r.lookups++
	result := make(map[string]string, len(purls))
	for _, purl := range purls {
		if v, ok := r.latest[purl]; ok {
			result[purl] = v
		}
	}
	return result, nil
}

func TestParsePackageJSONPins(t *testing.T) {
	content := `{
		"dependencies": {
			"runtime": "1.2.3",
			"alias": "npm:@scope/actual@8.0.0",
			"prerelease": "2.0.0-rc.1",
			"build": "3.0.0+metadata",
			"range": "^4.0.0",
			"tag": "latest",
			"workspace": "workspace:*"
		},
		"devDependencies": {
			"development": "5.0.0"
		},
		"optionalDependencies": {
			"optional": "6.0.0"
		},
		"peerDependencies": {
			"peer": "7.0.0"
		}
	}`

	got, err := parsePackageJSONPins(content)
	if err != nil {
		t.Fatalf("parsePackageJSONPins() error = %v", err)
	}

	want := map[string]string{
		"dependencies/runtime":          "1.2.3",
		"dependencies/alias":            "8.0.0",
		"dependencies/prerelease":       "2.0.0-rc.1",
		"dependencies/build":            "3.0.0+metadata",
		"devDependencies/development":   "5.0.0",
		"optionalDependencies/optional": "6.0.0",
		"peerDependencies/peer":         "7.0.0",
	}
	if len(got) != len(want) {
		t.Fatalf("parsePackageJSONPins() returned %d pins, want %d: %#v", len(got), len(want), got)
	}
	for location, version := range want {
		if got[location].Version != version {
			t.Errorf("parsePackageJSONPins()[%q].Version = %q, want %q", location, got[location].Version, version)
		}
	}
	if pin := got["dependencies/alias"]; pin.Name != "@scope/actual" || pin.PURL != "pkg:npm/%40scope/actual" {
		t.Errorf("alias pin = %#v, want canonical target package", pin)
	}
}

func TestParsePackageJSONPinsEmptyAndInvalid(t *testing.T) {
	got, err := parsePackageJSONPins(" \n")
	if err != nil {
		t.Fatalf("parsePackageJSONPins(empty) error = %v", err)
	}
	if len(got) != 0 {
		t.Fatalf("parsePackageJSONPins(empty) = %#v, want no pins", got)
	}

	if _, err := parsePackageJSONPins("{"); err == nil {
		t.Fatal("parsePackageJSONPins(invalid) returned nil error")
	}
}

func TestCheckPackageJSONOnlyChecksChangedExactPins(t *testing.T) {
	res := &fakeResolver{latest: map[string]string{"pkg:npm/added": "2.0.0"}}

	before := `{"dependencies":{"existing":"1.0.0"}}`
	after := `{"dependencies":{"existing":"1.0.0","added":"1.0.0","range":"^1.0.0"}}`

	got, err := CheckPackageJSON(before, after, res)
	if err != nil {
		t.Fatalf("CheckPackageJSON() error = %v", err)
	}
	if res.lookups != 1 {
		t.Fatalf("CheckPackageJSON() made %d resolver lookups, want 1", res.lookups)
	}
	if len(got) != 1 {
		t.Fatalf("CheckPackageJSON() returned %d mismatches, want 1: %#v", len(got), got)
	}
	if got[0].Name != "added" || got[0].Current != "1.0.0" || got[0].Latest != "2.0.0" {
		t.Fatalf("CheckPackageJSON() mismatch = %#v", got[0])
	}
}

func TestCheckPackageJSONScopedPackage(t *testing.T) {
	res := &fakeResolver{latest: map[string]string{"pkg:npm/%40scope/pkg": "2.0.0"}}

	before := `{}`
	after := `{"dependencies":{"@scope/pkg":"1.0.0"}}`

	got, err := CheckPackageJSON(before, after, res)
	if err != nil {
		t.Fatalf("CheckPackageJSON() error = %v", err)
	}
	if len(got) != 1 || got[0].Name != "@scope/pkg" {
		t.Fatalf("CheckPackageJSON() = %#v, want one mismatch for @scope/pkg", got)
	}
}

